// EH2 Build Error Record.
//
// settings.errorWorkflow fires this companion EXACTLY ONCE per failed
// execution, which is a guarantee n8n provides and hand-wiring cannot. r1 had a
// twelve-input collector here; any run where two error paths carried data would
// have written the record twice.
//
// The record carries no run_id: the Error Trigger payload exposes execution.id,
// execution.error, execution.lastNodeExecuted and workflow.id, but not
// workflow-internal state. The binder never needed run_id in a failure record --
// it needs to know a directory is not finished, and the ABSENCE of COMPLETE.json
// says that unambiguously for every failure mode, including the ones no
// in-workflow handler can catch.
try {
  var payload = $input.first().json || {};
  var execution = payload.execution || {};
  var workflow = payload.workflow || {};
  var err = execution.error || {};

  var executionId = String(execution.id === undefined || execution.id === null ? 'unknown' : execution.id);
  // The file name is built from the execution id, so screen it rather than
  // trusting it into a path.
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(executionId)) { throw new Error('execution-id-unsafe'); }

  var record = {
    schema_version: 'c2-discovery-error-record-v1',
    execution_id: executionId,
    workflow_id: workflow.id === undefined ? null : workflow.id,
    workflow_name: workflow.name === undefined ? null : workflow.name,
    last_node_executed: execution.lastNodeExecuted === undefined ? null : execution.lastNodeExecuted,
    error_message: err.message === undefined ? null : String(err.message),
    error_name: err.name === undefined ? null : String(err.name),
    error_node: err.node && err.node.name ? err.node.name : null,
    mode: execution.mode === undefined ? null : execution.mode,
    recorded_at: new Date().toISOString().replace(/\.\d+Z$/, 'Z')
  };

  var root = '/Users/jtsomwaru/projects/n8n-agent/clients/cohort-two-discovery';
  return [{ json: {
    file_path: root + '/out/errors/' + executionId + '.json',
    file_name: executionId + '.json',
    file_text: JSON.stringify(record, null, 2) + '\n'
  } }];
} catch (e) { throw new Error('EH2: ' + e.message); }
